        is_cycle = False
        if len(scc) >= 2:
            is_cycle = True
        elif len(scc) == 1:
            v = scc[0]
            if v in graph.get(v, set()):
                is_cycle = True
        if is_cycle:
            cycles.append(sorted(scc))

